import random
from collections import defaultdict

def simulate_one_game():
    ramp = list(range(1, 101))
    platform = ramp[:3]
    ramp = ramp[3:]
    ejected = []

    while len(ejected) < 100 and len(platform) > 0:
        piston = random.randint(0, len(platform)-1)
        ejected.append(platform[piston])

        if piston == 0:
            new_platform = []
            if len(platform) >=3:
                new_platform = [platform[1], platform[2]]
            elif len(platform) ==2:
                new_platform = [platform[1]]
            if ramp:
                new_platform.append(ramp.pop(0))
            platform = new_platform[:3]
        elif piston == 1:
            new_platform = []
            if len(platform) >=3:
                new_platform.append(platform[2])
            for _ in range(2):
                if ramp:
                    new_platform.append(ramp.pop(0))
            platform = new_platform[:3]
        else: # piston ==2
            new_platform = []
            if len(platform) >=2:
                new_platform.append(platform[1])
            for _ in range(2):
                if ramp:
                    new_platform.append(ramp.pop(0))
            platform = new_platform[:3]
    return ejected

SIM_COUNT = 20000
counts = defaultdict(int)
for _ in range(SIM_COUNT):
    res = simulate_one_game()
    for num in res:
        counts[num] += 1

max_count = -1
max_num = None
for num, cnt in counts.items():
    if cnt > max_count:
        max_count = cnt
        max_num = num

print(f"{max_num}")
print(f"{max_count/SIM_COUNT:.4f}")
